func parsePort(text string) (int, error) {
    port, err := strconv.Atoi(text)
    if err != nil || port < 1 || port > 65535 { return 0, fmt.Errorf("invalid port %q", text) }
    return port, nil
}
func TestParsePort(t *testing.T) {
    for _, tc := range []struct { name, input string; want int; invalid bool }{
        {"valid", "8080", 8080, false}, {"boundary", "65535", 65535, false},
        {"zero", "0", 0, true}, {"text", "bad", 0, true},
    } {
        t.Run(tc.name, func(t *testing.T) {
            got, err := parsePort(tc.input)
            if got != tc.want || (err != nil) != tc.invalid { t.Fatalf("got %d, %v", got, err) }
        })
    }
}

func TestLoadText(t *testing.T) {
    path := filepath.Join(t.TempDir(), "notes.txt")
