import (
    "context"
    "errors"
    "net/http"
    "github.com/go-chi/chi/v5"
)

func NewChiWork(work func(context.Context) error) http.Handler {
    router := chi.NewRouter()
    router.Use(func(next http.Handler) http.Handler {
        return http.HandlerFunc(func(w http.ResponseWriter, req *http.Request) {
            w.Header().Set("X-Content-Type-Options", "nosniff")
            next.ServeHTTP(w, req)
        })
    })
    router.Get("/work", func(w http.ResponseWriter, req *http.Request) {
        err := work(req.Context())
        switch {
        case errors.Is(err, context.Canceled):
            http.Error(w, "request canceled", http.StatusRequestTimeout)
        case errors.Is(err, context.DeadlineExceeded):
            http.Error(w, "work deadline", http.StatusGatewayTimeout)
        case err != nil:
            http.Error(w, "work failed", http.StatusBadGateway)
        default:
            w.WriteHeader(http.StatusNoContent)
        }
    })
    return router
}

