type Store interface { Load(string) (string, error) }
type StoreMock struct { mock.Mock }
func (s *StoreMock) Load(key string) (string, error) {
    args := s.Called(key)
    return args.String(0), args.Error(1)
}

func LoadTwice(store Store, key string) (string, error) {
    value, err := store.Load(key)
    if err != nil { return store.Load(key) }
    return value, nil
}

func TestStoreRecovery(t *testing.T) {
    unavailable := errors.New("unavailable")
    store := new(StoreMock)
    store.On("Load", "profile").Return("", unavailable).Once()
    store.On("Load", "profile").Return("Ada", nil).Once()
    value, err := LoadTwice(store, "profile")
    require.NoError(t, err)
    require.Equal(t, "Ada", value)
    store.AssertExpectations(t)
}
